 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    edge_color = next((v for v in set(v for row in g for v in row) if v != bg and
                       (sum(row[0] == v for row in g) + sum(row[-1] == v for row in g)) > 0), None)
    if edge_color is None:
        return g
    # Locate the two edge segments making the opposing panels.
    left = [r for r in range(h) if g[r][0] == edge_color]
    right = [r for r in range(h) if g[r][-1] == edge_color]
    segments = []
    for side, rows in ((0, left), (w-1, right)):
        if rows:
            segments.append((side, min(rows), max(rows)))
    if len(segments) != 2:
        return g
    (side_a, a0, a1), (side_b, b0, b1) = sorted(segments, key=lambda x: x[1])
    # Markers are non-background, non-edge cells in either panel.
    marker_color = next((v for row in g for v in row if v != bg and v != edge_color), None)
    if marker_color is None:
        return g
    fill_color = marker_color
    for r in range(h):
        if not (a0 <= r <= a1 or b0 <= r <= b1):
            continue
        for c in range(w):
            if g[r][c] == marker_color:
                # Extend from marker toward its bordering edge, leaving a 4 at the marker.
                edge_col = 0 if g[r][0] == edge_color else (w-1 if g[r][-1] == edge_color else None)
                if edge_col is not None:
                    step = 1 if edge_col == 0 else -1
                    ccur = edge_col + step
                    while ccur != c:
                        g[r][ccur] = fill_color
                        ccur += step
                    g[r][c] = 4
                # Project row occupancy into the opposite edge segment at matching offset.
                if a0 <= r <= a1:
                    other_side, other_lo, other_hi = side_b, b0, b1
                    target_r = other_lo + (r - a0)
                    src_side = side_a
                else:
                    other_side, other_lo, other_hi = side_a, a0, a1
                    target_r = other_lo + (r - b0)
                    src_side = side_b
                if target_r <= other_hi:
                    for cc in range(w):
                        if cc != (0 if g[target_r][0] == edge_color else w-1 if g[target_r][-1] == edge_color else -1):
                            g[target_r][cc] = fill_color
    return g
"
